use crate::support::*;

const BINDINGS: &[(&str, &str)] = &[
    (
        "src/bindings/mod.rs",
        "// THIS FILE IS AUTOMATICALLY GENERATED BY SPACETIMEDB. EDITS TO THIS FILE\n\
         mod user_table;\n\
         mod inherited;\n\
         pub use user_table::User;\n\
         pub use inherited::*;\n\
         pub(super) fn value() -> usize { let _ = User; inherited_value() }\n",
    ),
    (
        "src/bindings/user_table.rs",
        "// THIS FILE IS AUTOMATICALLY GENERATED BY SPACETIMEDB. EDITS TO THIS FILE\n\
         pub struct User;\n",
    ),
    (
        "src/bindings/inherited.rs",
        "pub fn inherited_value() -> usize {\n\
             use std::mem::size_of;\n\
             size_of::<u8>()\n\
         }\n",
    ),
];

#[test]
fn generated_bindings_have_no_findings_and_keep_their_bytes_after_fix() {
    let temp = tempdir().expect("create generated bindings fixture");
    fs::create_dir_all(temp.path().join("src/bindings")).expect("create bindings modules");
    fs::write(
        temp.path().join("Cargo.toml"),
        "[package]\nname = \"generated_bindings_fixture\"\nversion = \"0.1.0\"\nedition = \"2024\"\n\
         [lib]\ntest = false\nbench = false\n",
    )
    .expect("write fixture manifest");
    fs::write(
        temp.path().join("mend.toml"),
        "[visibility]\npub_in_path = \"permitted\"\n\
         [generated]\nmarkers = [\"@generated\", \"AUTOMATICALLY GENERATED\"]\nheader_lines = 5\n",
    )
    .expect("write fixture configuration");
    fs::write(
        temp.path().join("src/lib.rs"),
        "mod bindings;\nmod authored;\npub fn entry() -> usize { authored::value() + bindings::value() }\n",
    )
    .expect("write fixture root");
    fs::write(
        temp.path().join("src/authored.rs"),
        "pub fn value() -> usize { 1 }\n",
    )
    .expect("write authored module");
    for (relative, source) in BINDINGS {
        fs::write(temp.path().join(relative), source).expect("write generated module");
    }

    let manifest = temp.path().join("Cargo.toml");
    let report = run_mend_json(&manifest);
    assert!(
        report.findings.iter().any(|finding| {
            finding.path.ends_with("src/authored.rs")
                && finding.code == DiagnosticCode::NarrowToPubCrate
        }),
        "the authored visibility finding must remain: {report:#?}",
    );

    let output = mend_command_for(&manifest)
        .arg("--fix")
        .output()
        .expect("fix the bindings fixture");
    assert!(
        output.status.success(),
        "cargo-mend --fix failed: {}\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr),
    );
    for (relative, source) in BINDINGS {
        assert_eq!(
            fs::read(temp.path().join(relative)).expect("read generated module"),
            source.as_bytes(),
            "--fix changed {relative}; report: {report:#?}",
        );
    }
    assert!(
        report.findings.iter().all(|finding| {
            !std::path::Path::new(&finding.path)
                .components()
                .any(|component| component.as_os_str() == "bindings")
        }),
        "generated modules must have no findings: {report:#?}",
    );
}
